"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][43]={"university_physics_de:M43-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M43-L1 – Forschungsfragen, Hypothesen und prüfbare Modellvorhersagen<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M31: numerische Modellierung; M39:\nRelaxationsprozesse; M42-L6: Forschungsdokumentation. <a\nhref=\"index.html?course=university_physics&amp;module=M42&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Vorheriges Modul<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Aus einer physikalischen Annahme eine\nvorab quantifizierte und potenziell widerlegbare Prognose ableiten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Eine Forschungsfrage benennt Messgröße, System, Einflussvariable und\nrelevante Zeitskala. Eine prüfbare Hypothese sagt nicht nur „der Wert\nsinkt“, sondern legt ein Modell und eine beobachtbare Konsequenz fest.\n<strong>Widerlegbarkeit<\/strong> ist keine Garantie für Wahrheit: Eine\nAbweichung kann aus Messfehlern, falschen Anfangsbedingungen oder einem\nunpassenden Modell stammen. Dokumentiert werden deshalb auch\nAlternativen und eindeutige Entscheidungskriterien.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine lineare Relaxation in Richtung eines festen\nGleichgewichtswerts\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><annotation encoding=\"application/x-tex\">y_\\infty<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>d<\/mi><mi>y<\/mi><mi>/<\/mi><mi>d<\/mi><mi>t<\/mi><mo>=<\/mo><mi>−<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>y<\/mi><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>τ<\/mi><\/mrow><annotation encoding=\"application/x-tex\">dy/dt=-(y-y_\\infty)/\\tau<\/annotation><\/semantics><\/math>.\nTrennung der Variablen ergibt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(t)=y_\\infty+(y_0-y_\\infty)e^{-t/\\tau}<\/annotation><\/semantics><\/math>.\nDie Zeitkonstante\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>τ<\/mi><annotation encoding=\"application/x-tex\">\\tau<\/annotation><\/semantics><\/math>\nist die Zeit bis zur Verringerung der Anfangsabweichung auf den Anteil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">e^{-1}<\/annotation><\/semantics><\/math>;\nsie ist nicht die Halbwertszeit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau\\ln 2<\/annotation><\/semantics><\/math>.\nDas Modell setzt konstante Parameter und eine einzelne dominante\nRelaxationsskala voraus.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>+<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>τ<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">y(t)=y_\\infty+(y_0-y_\\infty)e^{-t/\\tau},\\qquad t_{1/2}=\\tau\\ln2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>In einem <strong>synthetischen<\/strong> Entspannungsversuch seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_0=10<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>y<\/mi><mi>∞<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y_\\infty=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>\nlautet die Prognose\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mn>2<\/mn><mo>+<\/mo><mn>8<\/mn><mi>/<\/mi><mi>e<\/mi><mo>≈<\/mo><mn>4<\/mn><mo>,<\/mo><mn>943<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y=2+8/e\\approx4{,}943<\/annotation><\/semantics><\/math>.\nEine unabhängige Beobachtung könnte diese konkrete Vorhersage prüfen.\nVor dem Versuch sollten Zeitfenster, Sensorgenauigkeit und die Kriterien\nfür auffällige Abweichungen feststehen. Die Abbildung zeigt\nausschließlich die Modellkurve.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_178_DE.svg\"\nalt=\"Exponentialkurve von zehn auf den Gleichgewichtswert zwei mit Markierung der Zeitkonstante bei drei Sekunden.\" />\n<figcaption aria-hidden=\"true\">Exponentialkurve von zehn auf den\nGleichgewichtswert zwei mit Markierung der Zeitkonstante bei drei\nSekunden.<\/figcaption>\n<\/figure>\n<p><em>Originale analytische Modellgrafik mit synthetischen\nParametern.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y(0)<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Bestimme die Halbwertszeit bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\tau=3\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum widerlegt eine einzelne abweichende Messung nicht sofort jede\nVersion des Modells?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mo>+<\/mo><mn>8<\/mn><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=2+8=10<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><mo>≈<\/mo><mn>2<\/mn><mo>,<\/mo><mn>079<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t_{1/2}=3\\ln2\\approx2{,}079\\,\\mathrm{s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Messunsicherheit, Parameterfehler und Modellvarianten müssen geprüft\nund voneinander getrennt werden.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Mehrfache Zeitskalen, temperaturabhängige Raten, Drift und Störungen\nkönnen die Ein-Exponential-Näherung verletzen. Eine angepasste Kurve auf\nTrainingsdaten ist keine unabhängige Vorhersage. Auch eine gute\nÜbereinstimmung beweist nicht die Einzigartigkeit der physikalischen\nErklärung.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Im nächsten Schritt wird geprüft, wie ein reales Messsignal durch die\nKalibrierung in eine physikalische Größe übergeht. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L1 – Forschungsfragen, Hypothesen und prüfbare Modellvorhersagen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L1 – Forschungsfragen, Hypothesen und prüfbare Modellvorhersagen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M43-L2 – Messkette, Kalibrierung und systematische Abweichungen<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M32: Sensorik und Kalibrierung;\nM43-L1: Modellvorhersagen.<\/p>\n<p><strong>Lernziel:<\/strong> Eine lineare Sensorkalibrierung\ninvertieren und den Einfluss eines Offsets unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Zwischen physikalischer Größe und veröffentlichter Zahl liegen\nSensor, Analogelektronik, Digitalisierung, Kalibrierung und\nDatenverarbeitung. Die Messkette beeinflusst das Ergebnis auch dann,\nwenn die Streuung sehr klein ist. Ein stabiler, aber unbekannter Offset\nkann hohe Präzision und schlechte Richtigkeit zugleich bewirken.\nReferenzpunkte und Kalibrierbedingungen sind deshalb zu\ndokumentieren.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Ein linearer Sensor werde durch\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mi>a<\/mi><mi>T<\/mi><mo>+<\/mo><mi>b<\/mi><\/mrow><annotation encoding=\"application/x-tex\">U=aT+b<\/annotation><\/semantics><\/math>\nmodelliert. Bei bekanntem Anstieg\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">a\\ne0<\/annotation><\/semantics><\/math>\nund Offset\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>U<\/mi><mo>−<\/mo><mi>b<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=(U-b)/a<\/annotation><\/semantics><\/math>.\nIst\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>\nunsicher, kann sein Beitrag zur Standardunsicherheit im linearen Modell\nüber\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>T<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>b<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial T/\\partial b=-1/a<\/annotation><\/semantics><\/math>\nbewertet werden. Die gesamte Unsicherheitsrechnung muss zusätzlich\nSignalunsicherheit, Kovarianzen und die Unsicherheit der Steigung\nberücksichtigen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mfrac><mrow><mi>U<\/mi><mo>−<\/mo><mi>b<\/mi><\/mrow><mi>a<\/mi><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mfrac><mrow><mi>∂<\/mi><mi>T<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>b<\/mi><\/mrow><\/mfrac><mo>=<\/mo><mi>−<\/mi><mfrac><mn>1<\/mn><mi>a<\/mi><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=\\frac{U-b}{a},\\qquad \\frac{\\partial T}{\\partial b}=-\\frac1a.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein <strong>synthetischer<\/strong> Sensor habe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">K<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">a=2\\,\\mathrm{mV/K}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>b<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">b=0{,}5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>10<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">U=10{,}5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=5\\,\\mathrm K<\/annotation><\/semantics><\/math>.\nWürde man den Offset übergehen, ergäbe sich fälschlich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">5{,}25\\,\\mathrm K<\/annotation><\/semantics><\/math>.\nDie Diagrammpunkte stammen aus dem Kalibrierungsmodell und sind keine\nMessdaten eines Geräts.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_165_DE.svg\"\nalt=\"Lineare Kennlinie des Sensors mit Offset und synthetischem Signalpunkt bei fünf Kelvin.\" />\n<figcaption aria-hidden=\"true\">Lineare Kennlinie des Sensors mit Offset\nund synthetischem Signalpunkt bei fünf Kelvin.<\/figcaption>\n<\/figure>\n<p><em>Eigene schematische Kalibriergrafik.<\/em><\/p>\n<p>Keine reale Gerätespezifikation.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welches\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>T<\/mi><annotation encoding=\"application/x-tex\">T<\/annotation><\/semantics><\/math>\nfolgt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>6<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">U=6{,}5\\,\\mathrm{mV}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Abweichung verursacht das Weglassen von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>b<\/mi><annotation encoding=\"application/x-tex\">b<\/annotation><\/semantics><\/math>\nim Beispiel?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>∂<\/mi><mi>T<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>b<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|\\partial T/\\partial b|<\/annotation><\/semantics><\/math>\nin\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">K<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{K/mV}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>T<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>6<\/mn><mo>,<\/mo><mn>5<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T=(6{,}5-0{,}5)/2=3\\,\\mathrm K<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5<\/mn><mo>,<\/mo><mn>25<\/mn><mo>−<\/mo><mn>5<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><\/mrow><annotation encoding=\"application/x-tex\">5{,}25-5=0{,}25\\,\\mathrm K<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">K<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">1/2=0{,}5\\,\\mathrm{K/mV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Lineare Kalibrierung ist nur im belegten Messbereich und für stabile\nUmgebungsbedingungen zulässig. Hysterese, Alterung, Nichtlinearität und\nreferenzabhängige Unsicherheiten erfordern zusätzliche Tests. Ein\nrechnerisch abgezogener Offset ist nicht automatisch exakt bekannt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Kalibrierung schafft eine Grundlage für vergleichbare\nGruppenmessungen; die Zuteilung und Verblindung werden anschließend\nbehandelt. <a href=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L2 – Messkette, Kalibrierung und systematische Abweichungen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L2 – Messkette, Kalibrierung und systematische Abweichungen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M43-L3 – Kontrollversuche, Randomisierung und verblindete Auswertung<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M32: Versuchsplanung; M43-L2:\nMesskette.<\/p>\n<p><strong>Lernziel:<\/strong> Einen synthetischen Gruppenunterschied\nberechnen und seine kausale Aussagekraft kritisch bewerten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Kontrollmessungen überprüfen den Aufbau, während Randomisierung\nbekannte und unbekannte Störfaktoren über viele Wiederholungen im\nErwartungswert verteilt. Eine verblindete Auswertung kann die\nunbeabsichtigte Beeinflussung durch Erwartungen reduzieren. Diese\nVerfahren ersetzen weder physikalische Kontrollbedingungen noch eine\nausreichende Stichprobengröße. Die Auswertungsentscheidung sollte\nmöglichst vor Kenntnis der Gruppenzuordnung dokumentiert werden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Als deskriptives Maß kann die Differenz der Gruppenmittelwerte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=\\overline y_B-\\overline y_A<\/annotation><\/semantics><\/math>\nverwendet werden. Die Zahl sagt für sich genommen nichts über die\nUnsicherheit oder einen kausalen Mechanismus. Bei unabhängigen\nZufallsstichproben und geeigneter Varianzmodellierung müsste auch der\nStandardfehler der Differenz bestimmt werden; Randomisierung reduziert\nsystematische Verzerrungen im Design, garantiert aber nicht identische\nGruppen in einer endlichen Stichprobe.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>G<\/mi><\/msub><mo>=<\/mo><mfrac><mn>1<\/mn><msub><mi>n<\/mi><mi>G<\/mi><\/msub><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><msub><mi>n<\/mi><mi>G<\/mi><\/msub><\/munderover><msub><mi>y<\/mi><mrow><mi>G<\/mi><mi>i<\/mi><\/mrow><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=\\overline y_B-\\overline y_A,\\qquad \\overline y_G=\\frac{1}{n_G}\\sum_{i=1}^{n_G}y_{Gi}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>In einem <strong>synthetischen<\/strong> Vergleich seien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>10<\/mn><mo>,<\/mo><mn>12<\/mn><mo>,<\/mo><mn>11<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=(10,12,11)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>13<\/mn><mo>,<\/mo><mn>14<\/mn><mo>,<\/mo><mn>12<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B=(13,14,12)<\/annotation><\/semantics><\/math>\nin gleichen Einheiten. Dann folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>=<\/mo><mn>11<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_A=11<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>=<\/mo><mn>13<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_B=13<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=2<\/annotation><\/semantics><\/math>.\nDas Diagramm stellt alle sechs Werte dar, damit die geringe\nStichprobengröße sichtbar bleibt. Ein experimentell interpretierbarer\nEffekt setzt ein passendes Zuteilungsverfahren, eine kontrollierte\nMesskette und die Beschreibung möglicher Störgrößen voraus.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_088_DE.svg\"\nalt=\"Sechs Einzelwerte zweier Versuchsgruppen mit eingezeichneten Mittelwerten elf und dreizehn.\" />\n<figcaption aria-hidden=\"true\">Sechs Einzelwerte zweier Versuchsgruppen\nmit eingezeichneten Mittelwerten elf und dreizehn.<\/figcaption>\n<\/figure>\n<p><em>Eigene Punktgrafik mit künstlichen Übungswerten.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Bestimme\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Δ<\/mi><annotation encoding=\"application/x-tex\">\\Delta<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>5<\/mn><mo>,<\/mo><mn>7<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=(5,7)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>B<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>8<\/mn><mo>,<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">B=(8,10)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum belegt die bloße Mittelwertdifferenz noch keine\nKausalität?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Entscheidung sollte vor dem Entblinden feststehen?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>A<\/mi><\/msub><mo>=<\/mo><mn>6<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_A=6<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mover><mi>y<\/mi><mo accent=\"true\">¯<\/mo><\/mover><mi>B<\/mi><\/msub><mo>=<\/mo><mn>9<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\overline y_B=9<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=3<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Mögliche Störgrößen, Auswahl, Kalibrierabweichungen und\nZufallsschwankungen bleiben ungeklärt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Beispielsweise Ausschlusskriterien, primäre Zielgröße und\nAuswerteplan.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Bei nur drei Werten je Gruppe ist die statistische Unsicherheit\nerheblich; die Balken zeigen weder Konfidenzintervall noch Signifikanz.\nWenn Randomisierung und Verblindung fachlich oder ethisch unmöglich\nsind, müssen Einschränkungen und Alternativen offengelegt werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die nächste Lektion verknüpft Messgrößen mit korrelierten\nUnsicherheitsbeiträgen. <a href=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L3 – Kontrollversuche, Randomisierung und verblindete Auswertung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L3 – Kontrollversuche, Randomisierung und verblindete Auswertung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M43-L4 – Unsicherheitsbudget, Kovarianz und Fehlerfortpflanzung<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M32: Unsicherheitsrechnung; M43-L2:\nKalibrierung; M43-L3: Gruppenvergleich.<\/p>\n<p><strong>Lernziel:<\/strong> Den Einfluss korrelierter Eingangsdaten\nauf eine abgeleitete Standardunsicherheit berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Mehrere Messwerte können von derselben Kalibrierung, Umgebung oder\nDatenverarbeitung abhängen. Dann sind ihre Unsicherheiten nicht\nunabhängig. Bei der Differenz zweier gemeinsam driftender Sensoren kann\npositive Korrelation einen Teil der gemeinsamen Störung aufheben; bei\nSummen wirkt sie häufig verstärkend. Ein Unsicherheitsbudget trennt die\nKomponenten und benennt ihre Abhängigkeiten.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>z<\/mi><mo>=<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">z=x_1-x_2<\/annotation><\/semantics><\/math>\nergibt lineare Fehlerfortpflanzung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>u<\/mi><mi>z<\/mi><mn>2<\/mn><\/msubsup><mo>=<\/mo><msubsup><mi>u<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>u<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mo>−<\/mo><mn>2<\/mn><mi>ρ<\/mi><msub><mi>u<\/mi><mn>1<\/mn><\/msub><msub><mi>u<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">u_z^2=u_1^2+u_2^2-2\\rho u_1u_2<\/annotation><\/semantics><\/math>,\nsofern die Standardunsicherheiten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_i<\/annotation><\/semantics><\/math>\nund der Korrelationskoeffizient\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ρ<\/mi><annotation encoding=\"application/x-tex\">\\rho<\/annotation><\/semantics><\/math>\nbekannt sind. Dies folgt aus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><mrow><mi mathvariant=\"normal\">V<\/mi><mi mathvariant=\"normal\">a<\/mi><mi mathvariant=\"normal\">r<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mn>2<\/mn><mrow><mi mathvariant=\"normal\">C<\/mi><mi mathvariant=\"normal\">o<\/mi><mi mathvariant=\"normal\">v<\/mi><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>X<\/mi><mn>1<\/mn><\/msub><mo>,<\/mo><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{Var}(X_1-X_2)=\\mathrm{Var}(X_1)+\\mathrm{Var}(X_2)-2\\mathrm{Cov}(X_1,X_2)<\/annotation><\/semantics><\/math>.\nFür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>−<\/mi><mn>1<\/mn><mo>≤<\/mo><mi>ρ<\/mi><mo>≤<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">-1\\le\\rho\\le1<\/annotation><\/semantics><\/math>\nist die Varianz bei konsistenten Eingangsgrößen nicht negativ.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><msubsup><mi>u<\/mi><mn>1<\/mn><mn>2<\/mn><\/msubsup><mo>+<\/mo><msubsup><mi>u<\/mi><mn>2<\/mn><mn>2<\/mn><\/msubsup><mo>−<\/mo><mn>2<\/mn><mi>ρ<\/mi><msub><mi>u<\/mi><mn>1<\/mn><\/msub><msub><mi>u<\/mi><mn>2<\/mn><\/msub><\/mrow><\/msqrt><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mi>z<\/mi><mo>=<\/mo><msub><mi>x<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>x<\/mi><mn>2<\/mn><\/msub><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">u_z=\\sqrt{u_1^2+u_2^2-2\\rho u_1u_2},\\qquad z=x_1-x_2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für <strong>synthetische<\/strong> Messwerte mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_1=0{,}2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_2=0{,}3<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0{,}5<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>u<\/mi><mi>z<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mn>0<\/mn><mo>,<\/mo><mn>04<\/mn><mo>+<\/mo><mn>0<\/mn><mo>,<\/mo><mn>09<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>06<\/mn><\/mrow><\/msqrt><mo>=<\/mo><msqrt><mrow><mn>0<\/mn><mo>,<\/mo><mn>07<\/mn><\/mrow><\/msqrt><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>265<\/mn><\/mrow><annotation encoding=\"application/x-tex\">u_z=\\sqrt{0{,}04+0{,}09-0{,}06}=\\sqrt{0{,}07}\\approx0{,}265<\/annotation><\/semantics><\/math>.\nBei unabhängigen Eingängen\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=0<\/annotation><\/semantics><\/math>)\nergäbe sich dagegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mrow><mn>0<\/mn><mo>,<\/mo><mn>13<\/mn><\/mrow><\/msqrt><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>361<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt{0{,}13}\\approx0{,}361<\/annotation><\/semantics><\/math>.\nDie Abbildung zeigt die kontinuierliche Abhängigkeit von der\nKorrelation; sie ist keine aus Rohdaten geschätzte\nKorrelationskurve.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_052_DE.svg\"\nalt=\"Standardunsicherheit einer Sensordifferenz in Abhängigkeit vom Korrelationskoeffizienten.\" />\n<figcaption aria-hidden=\"true\">Standardunsicherheit einer\nSensordifferenz in Abhängigkeit vom\nKorrelationskoeffizienten.<\/figcaption>\n<\/figure>\n<p><em>Originale Kurve aus der analytischen Kovarianzformel mit\nsynthetischen Unsicherheiten.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>z<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_z<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>u<\/mi><mi>z<\/mi><\/msub><annotation encoding=\"application/x-tex\">u_z<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ρ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\rho=-1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Kann man Korrelationen bei gemeinsam kalibrierten Sensoren\ngrundsätzlich ignorieren?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|0{,}3-0{,}2|=0{,}1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><mo>+<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0{,}3+0{,}2=0{,}5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nein, die gemeinsame Ursache kann das Unsicherheitsbudget wesentlich\nverändern.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Formel ist für den linearen Unterschied exakt in Varianzen. Für\nallgemeine nichtlineare Funktionen gilt die GUM-Linearisierung nur bei\ngeeigneten lokalen Näherungen; bei stark nichtlinearen Modellen können\nMonte-Carlo-Verfahren oder andere Methoden nötig sein. Der Wert von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ρ<\/mi><annotation encoding=\"application/x-tex\">\\rho<\/annotation><\/semantics><\/math>\nmuss begründet und darf nicht willkürlich gewählt werden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Unsicherheit beantwortet, wie gut eine Zahl bekannt ist. Als\nNächstes wird gefragt, ob die Modelldaten die gesuchten Parameter\nüberhaupt bestimmen können. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L4 – Unsicherheitsbudget, Kovarianz und Fehlerfortpflanzung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L4 – Unsicherheitsbudget, Kovarianz und Fehlerfortpflanzung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M43-L5 – Parametersensitivität, Identifizierbarkeit und Messzeitpunkte<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M31: inverse Probleme; M43-L1:\nRelaxationsmodell; M43-L4: Unsicherheitsbudget.<\/p>\n<p><strong>Lernziel:<\/strong> Erklären, warum manche Parameter aus einem\neinzelnen Messzeitpunkt nicht identifiziert werden können.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Modell kann gut zu Messdaten passen und trotzdem nicht eindeutig\nkalibrierbar sein. <strong>Identifizierbarkeit<\/strong> beschreibt, ob\nverschiedene Parameterwerte überhaupt unterscheidbare Vorhersagen\nerzeugen. Eine geringe Sensitivität macht die Schätzung störanfällig;\nvöllig identische Vorhersagen begründen strukturelle\nNichtidentifizierbarkeit. Für die Messplanung muss daher geprüft werden,\nan welchen Zeitpunkten mehrere Parameter tatsächlich unterschiedliche\nSpuren hinterlassen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo>;<\/mo><mi>A<\/mi><mo>,<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mi>A<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(t;A,k)=A e^{-kt}<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A&gt;0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k&gt;0<\/annotation><\/semantics><\/math>\ngelten die Sensitivitäten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>A<\/mi><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial A=e^{-kt}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>k<\/mi><mo>=<\/mo><mi>−<\/mi><mi>A<\/mi><mi>t<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial k=-At e^{-kt}<\/annotation><\/semantics><\/math>.\nZum Zeitpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>\nhängt das Signal nur von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nab; die Sensitivität auf\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\nverschwindet. Mit zwei ideal rauschfreien Messwerten bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t_0=0<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t_1&gt;0<\/annotation><\/semantics><\/math>\nlässt sich im Modell zuerst\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">A=y(0)<\/annotation><\/semantics><\/math>\nund dann\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mi>−<\/mi><mrow><mi mathvariant=\"normal\">ln<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>A<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>/<\/mi><msub><mi>t<\/mi><mn>1<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">k=-\\ln[y(t_1)/A]/t_1<\/annotation><\/semantics><\/math>\nbestimmen, sofern\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>t<\/mi><mn>1<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>&lt;<\/mo><mi>A<\/mi><\/mrow><annotation encoding=\"application/x-tex\">0&lt;y(t_1)&lt;A<\/annotation><\/semantics><\/math>.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mfrac><mrow><mi>∂<\/mi><mi>y<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>A<\/mi><\/mrow><\/mfrac><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><mfrac><mrow><mi>∂<\/mi><mi>y<\/mi><\/mrow><mrow><mi>∂<\/mi><mi>k<\/mi><\/mrow><\/mfrac><mo>=<\/mo><mi>−<\/mi><mi>A<\/mi><mi>t<\/mi><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>k<\/mi><mi>t<\/mi><\/mrow><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\frac{\\partial y}{\\partial A}=e^{-kt},\\qquad \\frac{\\partial y}{\\partial k}=-At e^{-kt}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>In einem <strong>synthetischen<\/strong> Modell ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A=8<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k=0{,}25\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>.\nDann gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(0)=8<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>4<\/mn><mo>,<\/mo><mn>852<\/mn><\/mrow><annotation encoding=\"application/x-tex\">y(2\\,\\mathrm{s})=8e^{-0{,}5}\\approx4{,}852<\/annotation><\/semantics><\/math>.\nDie zwei eingezeichneten Punkte genügen in diesem idealisierten Modell\nzur Bestimmung beider Parameter. Würde ausschließlich bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>\ngemessen, wäre\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\nbeliebig und damit nicht identifizierbar.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_263_DE.svg\"\nalt=\"Exponentialabfall mit Beobachtung bei null und zwei Sekunden; fehlende Sensitivität auf k bei t gleich null.\" />\n<figcaption aria-hidden=\"true\">Exponentialabfall mit Beobachtung bei\nnull und zwei Sekunden; fehlende Sensitivität auf k bei t gleich\nnull.<\/figcaption>\n<\/figure>\n<p><em>Originale analytische Modellkurve, keine experimentelle\nMessung.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>∂<\/mi><mi>y<\/mi><mi>/<\/mi><mi>∂<\/mi><mi>k<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\partial y/\\partial k<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum verbessert ein zweiter Messzeitpunkt die Schätzung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\naus\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>A<\/mi><mo>=<\/mo><mn>8<\/mn><\/mrow><annotation encoding=\"application/x-tex\">A=8<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">t=2\\,\\mathrm s<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>8<\/mn><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">y(2)=8e^{-0{,}5}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>0<\/mn><annotation encoding=\"application/x-tex\">0<\/annotation><\/semantics><\/math>,\nunabhängig von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>A<\/mi><annotation encoding=\"application/x-tex\">A<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Eine spätere Messung hängt von der Abklingrate ab, während\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>t<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">t=0<\/annotation><\/semantics><\/math>\ndie Amplitude festlegt.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi mathvariant=\"normal\">−<\/mi><mn mathvariant=\"normal\">1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">k=0{,}5/2=0{,}25\\,\\mathrm{s^{-1}}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Rauschen, Hintergrundoffset, begrenzte Auflösung und zu kleine oder\nzu große Messzeiten können die praktische Identifizierbarkeit stark\nverschlechtern. Parameterkorrelation und lokale Jacobimatrix müssen bei\nmehreren Parametern und komplexeren Modellen berücksichtigt werden. Zwei\nPunkte sind kein robustes Versuchsdesign.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Nach der Parameterbestimmung folgt die zentrale Frage, ob die\nResiduen überhaupt mit dem angenommenen Fehlermodell vereinbar sind. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L5 – Parametersensitivität, Identifizierbarkeit und Messzeitpunkte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L5 – Parametersensitivität, Identifizierbarkeit und Messzeitpunkte · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M43-L6 – Residuen, gewichtetes Chi-Quadrat und Modellangemessenheit<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M16: Statistik; M31: Validierung;\nM43-L5: Identifizierbarkeit.<\/p>\n<p><strong>Lernziel:<\/strong> Standardisierte Residuen berechnen und ein\ngewichtetes Gütemaß unter seinen Modellannahmen deuten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein guter visueller Kurvenverlauf ist kein zuverlässiger Modelltest.\nDie Differenzen zwischen Beobachtung und Modell müssen mit der\nMessgenauigkeit und möglichen Abhängigkeiten verglichen werden. Für\nunkorrelierte Messungen mit bekannten Standardabweichungen kann die\ngewichtete Quadratsumme ein Diagnosewerkzeug sein. Ein reduzierter Wert\nnahe eins ist jedoch nur unter den passenden Modellannahmen zu erwarten\nund garantiert keine physikalisch richtige Beschreibung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für Messwerte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>y<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">y_i<\/annotation><\/semantics><\/math>\nmit Modellvorhersage\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>θ<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f_i(\\hat\\theta)<\/annotation><\/semantics><\/math>\nund bekanntem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_i&gt;0<\/annotation><\/semantics><\/math>\nlautet die gewichtete Summe\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=\\sum_i[(y_i-f_i)/\\sigma_i]^2<\/annotation><\/semantics><\/math>.\nWenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nunabhängige Parameter anhand derselben\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nDatenpunkte geschätzt werden und reguläre Bedingungen vorliegen, wird\noft\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\nu=n-p<\/annotation><\/semantics><\/math>\nals effektive Residuen-Freiheitsgradzahl verwendet;\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mi>/<\/mi><mi>ν<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2_\\mathrm{red}=\\chi^2/\\nu<\/annotation><\/semantics><\/math>\nist für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu&gt;0<\/annotation><\/semantics><\/math>\ndefiniert. Die übliche Chi-Quadrat-Referenzverteilung benötigt\nzusätzliche Annahmen, etwa korrekte Fehlerkovarianz und näherungsweise\nnormalverteilte Fehler.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mi>f<\/mi><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>θ<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/msup><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><mfrac><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mrow><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=\\sum_{i=1}^n\\left(\\frac{y_i-f_i(\\hat\\theta)}{\\sigma_i}\\right)^2,\\qquad \\chi^2_{\\mathrm{red}}=\\frac{\\chi^2}{n-p}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Ein <strong>synthetischer<\/strong> Dreipunktvergleich hat\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y=(2,4,5)<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>f<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>3<\/mn><mo>,<\/mo><mn>8<\/mn><mo>,<\/mo><mn>5<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">f=(2{,}1,3{,}8,5{,}1)<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>σ<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\sigma=(0{,}1,0{,}2,0{,}1)<\/annotation><\/semantics><\/math>.\nDie standardisierten Residuen sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>−<\/mi><mn>1<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mi>−<\/mi><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(-1,1,-1)<\/annotation><\/semantics><\/math>\nund damit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2=3<\/annotation><\/semantics><\/math>.\nFalls genau ein unabhängig identifizierbarer Modellparameter aus diesen\ndrei Werten angepasst wurde\n(<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=1<\/annotation><\/semantics><\/math>),\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>χ<\/mi><mrow><mi mathvariant=\"normal\">r<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">d<\/mi><\/mrow><mn>2<\/mn><\/msubsup><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\chi^2_\\mathrm{red}=1{,}5<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt nur standardisierte Residuen; eine formale\np-Wert-Interpretation wird daraus nicht abgeleitet.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_318_DE.svg\"\nalt=\"Drei standardisierte Residuen mit den Werten minus eins, plus eins und minus eins.\" />\n<figcaption aria-hidden=\"true\">Drei standardisierte Residuen mit den\nWerten minus eins, plus eins und minus eins.<\/figcaption>\n<\/figure>\n<p><em>Originale schematische Residualgrafik auf Basis synthetischer\nZahlen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>χ<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">\\chi^2<\/annotation><\/semantics><\/math>\nfür standardisierte Residuen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(1,2,0)<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie viele nominale Freiheitsgrade entstehen für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>10<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=10<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>p<\/mi><mo>=<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">p=3<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum kann ein kleines Chi-Quadrat ebenfalls verdächtig sein?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mn>1<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>2<\/mn><mn>2<\/mn><\/msup><mo>+<\/mo><msup><mn>0<\/mn><mn>2<\/mn><\/msup><mo>=<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1^2+2^2+0^2=5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ν<\/mi><mo>=<\/mo><mn>10<\/mn><mo>−<\/mo><mn>3<\/mn><mo>=<\/mo><mn>7<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\nu=10-3=7<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Mögliche Überschätzung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mi>i<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\sigma_i<\/annotation><\/semantics><\/math>,\nKorrelationen oder überangepasste Modelle prüfen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Sind Fehler korreliert, muss die gesamte Kovarianzmatrix\nberücksichtigt werden; diagonal gewichtete Residuen können dann\nirreführend sein. Bei kleinen Stichproben, nichtlinearer Anpassung,\nunbekannten Varianzen und Randparametern gilt die einfache\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>−<\/mo><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n-p<\/annotation><\/semantics><\/math>-Interpretation\nnicht automatisch. Modellgüte sollte auch an unabhängigen Daten geprüft\nwerden.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die Abschlusslektion integriert Forschungsdesign, Modellprüfung und\nAuswertung zu einem prüfbaren Arbeitsablauf. <a\nhref=\"index.html?course=university_physics&amp;module=M43&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://itl.nist.gov/div898/handbook/pmd/section1/pmd143.htm\">NIST – Weighted Least Squares Regression<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L6 – Residuen, gewichtetes Chi-Quadrat und Modellangemessenheit · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.itl.nist.gov/div898/handbook/pmd/section4/pmd452.htm\">NIST – Accounting for Non-Constant Variation Across the Data<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L6 – Residuen, gewichtetes Chi-Quadrat und Modellangemessenheit · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L6 – Residuen, gewichtetes Chi-Quadrat und Modellangemessenheit · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M43-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M43-L7 – Forschungsprojekt: externe Validierung und transparente Ergebnisdarstellung<\/h1>\n<p><strong>Kursbereich:<\/strong> M43 – Master: Modellkritik und wissenschaftliche Forschungsdurchführung<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M43-L1–L6: Vorhersage,\nKalibrierung, Design, Unsicherheit und Modellprüfung.<\/p>\n<p><strong>Lernziel:<\/strong> Ein kleines physikalisches\nValidierungsbeispiel mit vorab getrennten Prüfdaten abschließen und\nseine Aussagegrenzen dokumentieren.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Forschungsbericht macht aus der Abfolge von Entscheidungen ein\nüberprüfbares Ergebnis: Forschungsfrage, Annahmen, Messprotokoll,\nRohdaten, Kalibrierung, Verarbeitung, Codeversion, Unsicherheitsbudget,\nModellprüfung und nachvollziehbare Schlussfolgerung. <strong>Externe\nValidierung<\/strong> bedeutet hier, dass die Daten nicht zur\nModellanpassung oder zur nachträglichen Auswahl der Parameter verwendet\nwurden. Transparenz schließt negative Ergebnisse, alternative Modelle\nund Abweichungen vom ursprünglichen Plan ein.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Als einfaches, stets mit Einheit angegebenes Maß für einen vorab\nfestgelegten Holdout-Datensatz kann der mittlere absolute Fehler\nverwendet werden:\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><msup><mi>n<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><msub><mo>∑<\/mo><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=n^{-1}\\sum_i|y_i-\\hat y_i|<\/annotation><\/semantics><\/math>.\nAnders als ein Anpassungsfehler misst er eine außerhalb der Anpassung\nliegende Vorhersageabweichung, sofern der Datensplit tatsächlich\nunabhängig blieb. Er sagt noch nichts über Fehlerverteilung,\nMessunsicherheit, systematische Verzerrung oder erfolgreiche\nGeneralisierung auf andere Bedingungen aus.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mfrac><mn>1<\/mn><mi>n<\/mi><\/mfrac><munderover><mo>∑<\/mo><mrow><mi>i<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><mi>n<\/mi><\/munderover><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msub><mi>y<\/mi><mi>i<\/mi><\/msub><mo>−<\/mo><msub><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mi>i<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=\\frac{1}{n}\\sum_{i=1}^{n}|y_i-\\widehat y_i|.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Vier <strong>synthetische, vorab zurückgehaltene<\/strong> Messwerte\nseien\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>y<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>3<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>5<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">y=(2,3,4,5)<\/annotation><\/semantics><\/math>\nEinheiten. Die eingefrorene Modellvorhersage lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>y<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>9<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>4<\/mn><mo>,<\/mo><mn>8<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\hat y=(2{,}2,2{,}9,4{,}1,4{,}8)<\/annotation><\/semantics><\/math>.\nDer absolute Fehlervektor ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0{,}2,0{,}1,0{,}1,0{,}2)<\/annotation><\/semantics><\/math>;\nsomit ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>15<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=0{,}15<\/annotation><\/semantics><\/math>\nEinheiten. Die Punktgrafik zeigt Vorhersage gegen Beobachtung und die\nideale Diagonale. Der Datensatz und die Holdout-Unabhängigkeit sind\n<strong>didaktische Annahmen<\/strong>, keine überprüfte\nForschungsstudie.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_242_DE.svg\"\nalt=\"Vier künstliche Prognose-gegen-Beobachtung-Punkte mit idealer Identitätsgerade.\" />\n<figcaption aria-hidden=\"true\">Vier künstliche\nPrognose-gegen-Beobachtung-Punkte mit idealer\nIdentitätsgerade.<\/figcaption>\n<\/figure>\n<p><em>Eigene Validierungsskizze; die Daten sind vollständig\nsynthetisch.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}<\/annotation><\/semantics><\/math>\nfür Fehlerbeträge\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><mo>,<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">(0{,}2,0{,}4)<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Warum ist das nachträgliche Anpassen auf dem Testsatz\nproblematisch?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Bestandteile müssen einen reproduzierbaren Abschlussbericht\nbegleiten?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">A<\/mi><mi mathvariant=\"normal\">E<\/mi><\/mrow><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathrm{MAE}=0{,}3<\/annotation><\/semantics><\/math>\nin den Messwerteinheiten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Der Testsatz wird Teil der Modellauswahl; die gemeldete Fehlerzahl\nist dann keine unabhängige Prüfung mehr.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Messprotokoll, Rohdaten oder dokumentierte Zugangsregeln,\nKalibrierungen, Code/Umgebung, Unsicherheiten, Abweichungen und\nQuellen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Vier künstliche Punkte und eine einzige Kennzahl können kein\nForschungsprogramm validieren. Fehler können korreliert sein; eine\nvollständige Aussage braucht Unsicherheiten, physikalische\nGültigkeitsbereiche, Sicherheits- und Ethikprüfung sowie gegebenenfalls\nexterne Replikation. FAIR-Datenprinzipien verlangen dokumentierte\nZugänglichkeit, nicht zwingend die öffentliche Freigabe sämtlicher\nRohdaten.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die abschließende Lektion verbindet Modellvorhersage, Messprotokoll,\nunabhängig zurückgehaltene Prüfdaten und die Grenzen der\nValidierung.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/programs-projects/nistsematech-engineering-statistics-handbook\">NIST – NIST/SEMATECH Engineering Statistics Handbook<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L7 – Forschungsprojekt: externe Validierung und transparente Ergebnisdarstellung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.dfg.de/en/basics-topics/basics-and-principles-of-funding/good-research-practice/code-of-conduct\">DFG – Code of Conduct: Guidelines for Safeguarding Good Research Practice<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L7 – Forschungsprojekt: externe Validierung und transparente Ergebnisdarstellung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.nist.gov/pml/nist-technical-note-1297/nist-tn-1297-5-combined-standard-uncertainty\">NIST – Combined Standard Uncertainty, Technical Note 1297<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Fachlicher Bezug zur Lektion: M43-L7 – Forschungsprojekt: externe Validierung und transparente Ergebnisdarstellung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
